# Registry of all time locales.
# Source a locale file on demand and cache the result.

.time_locale_cache <- new.env(parent = emptyenv())

get_time_locale <- function(code) {
  if (exists(code, envir = .time_locale_cache)) {
    return(get(code, envir = .time_locale_cache))
  }
  locale_dir <- file.path(dirname(sys.frame(sys.nframe())$ofile), ".")
  path <- file.path(locale_dir, paste0(code, ".R"))
  if (!file.exists(path)) return(NULL)
  env <- new.env(parent = baseenv())
  source(path, local = env)
  var_name <- paste0("locale_", gsub("-", "_", code))
  if (!exists(var_name, envir = env)) return(NULL)
  locale <- get(var_name, envir = env)
  assign(code, locale, envir = .time_locale_cache)
  locale
}
